from pathlib import Path
root=Path(__file__).parent
f=root/'build_spec.py'
s=f.read_text(encoding='utf-8')
a=s.index("h('5 Требования к программной документации')")
b=s.index("h('6 Технико-экономические показатели')", a)
c=s.index("h('7 Стадии и этапы разработки')", b)
e=s.index("h('8 Порядок контроля и приёмки')", c)
docs=s[a:b].replace("h('5 Требования к программной документации')", "h('7 Требования к документации')")
docs=docs.replace('требования и порядок ручной проверки в TESTING.md.', 'требования и порядок ручной проверки в TESTING.md, руководство пользователя docs/USER_GUIDE.md и описание архитектуры со схемой docs/ARCHITECTURE.md.')
docs += "p('Для запуска установите Node.js 20.19+ или 22.12+ с npm. Откройте терминал в каталоге sec-barmen. Последовательно выполните npm ci, npm run build, npm run start:local. После сообщения о запуске откройте http://localhost:4242. Файл .env и банковские ключи не требуются. Сервер останавливается Ctrl+C. При занятом порте 4242 завершите ранее запущенный экземпляр. При изменении клиентского кода повторите сборку. Для разработки используйте npm run dev:local и адрес, показанный Vite в терминале.')\n"
stages=s[c:e].replace("h('7 Стадии и этапы разработки')", "h('9 Этапы и сроки разработки')").replace("p('7.", "p('9.")
new="""h('5 Требования к интерфейсу')
p('Интерфейс должен быть русскоязычным и адаптивным. Меню, кнопки записи и входа должны иметь понятные подписи. Поля должны обозначать назначение вводимых данных. Выбранный способ оплаты должен визуально отличаться от остальных. Состояния ожидания, подтверждения и ошибки должны быть различимы. Все основные действия доступны мышью и клавиатурой; на узком экране элементы не перекрывают друг друга. Поведение страниц, FAQ и форм определено в подразделе 4.1.')
h('6 Критерии приёмки')
p('Поставка принимается при успешной установке и сборке по разделу 7, доступности всех основных страниц и выполнении требований разделов 4 и 5. Каждое обязательное требование проверяется хотя бы одним сценарием; все обязательные сценарии должны завершиться ожидаемым результатом. Сравниваются цены, проверяются границы ввода, повторная отправка, навигация, документы, выбор оплаты и согласия. Получение установленного сообщения о недоступной локальной оплате считается ожидаемым результатом.')
"""
s=s[:a]+new+docs+s[e:]
pos=s.index("h('Нормативные ссылки', 2)")
s=s[:pos]+stages+s[pos:]
s=s.replace('выполнении требований раздела 4', 'выполнении требований разделов 4–6')
s=s.replace('Структура разделов настоящего ТЗ принята по ГОСТ 19.201–78.', 'Состав разделов согласован с ГОСТ 19.201–78; нумерация соответствует заданию практической работы № 1.')
f.write_text(s,encoding='utf-8')

old=[1,3,4,6,7,9,11,12]
types=['Ошибка граничного значения','Логическая ошибка выбора','Интерфейсная ошибка','Логическая ошибка состояния формы','Интерфейсная ошибка','Ошибка отображения данных','Навигационная ошибка','Ошибка доступности содержимого']
lines=(root/'BUGS.md').read_text(encoding='utf-8').splitlines()
rows={int(x.split('|')[1].strip()):x.split('|')[2:-1] for x in lines if x.startswith('| ') and x.split('|')[1].strip().isdigit()}
out=['# Восемь намеренных ошибок — только для авторов','', 'Перед каждым сценарием перезагрузите страницу. Работайте с локальной версией.', 'Данные формы: Анна, +7 999 123-45-67, student@example.com; исключения указаны в шагах.', '', '| ID | Тип | Шаги обнаружения | Фактический результат | Ожидаемый результат |','|---|---|---|---|---|']
for i,(n,t) in enumerate(zip(old,types),1):
    out.append('| BUG-%02d | %s | %s |'%(i,t,' | '.join(x.strip() for x in rows[n])))
out += ['', 'Соответствие прежним номерам: '+', '.join(f'BUG-{i:02d} → {n}' for i,n in enumerate(old,1))+'.', '', 'BUG-01 и BUG-04 могут проявляться вместе. Для отдельной проверки BUG-04 используйте пустое имя.', 'BUG-02 проверяется без проведения платежа. BUG-07 относится к внешней ссылке; для проверки нужен интернет.', 'BUG-08 проверяется через ссылку «Согласие на рассылку» на странице оформления.', '', 'Места реализации: validation.ts (BUG-01), PaymentPage.tsx (BUG-02, BUG-06), SiteHeader.tsx (BUG-03), ContactForm.tsx (BUG-04), FaqCard.tsx (BUG-05), Layout.tsx (BUG-07), App.tsx (BUG-08).', '', 'Исправлены прежние № 2, 5, 8 и 10: пробелы и переносы сообщения, переход «Контакты», обязательность всех согласий.', 'Список описывает намеренные изменения и не является утверждением об отсутствии иных дефектов.']
(root/'BUGS.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
